import type { DndObserver } from 'dragdoll/dnd-observer';
import type { DraggableOptions } from 'dragdoll/draggable';
import { Draggable } from 'dragdoll/draggable';
import type { Sensor } from 'dragdoll/sensors';
import type { Accessor } from 'solid-js';
import { createEffect, createMemo, createSignal, onCleanup } from 'solid-js';
import { areConfigsEqual } from '../utils/are-configs-equal.js';
import type { MaybeAccessor } from '../utils/maybe-accessor.js';
import { resolveMaybeAccessor } from '../utils/maybe-accessor.js';
import { useDndObserverContext } from './use-dnd-observer-context.js';

export interface UseDraggableSettings<S extends Sensor[] = Sensor[]>
  extends Partial<DraggableOptions<S>> {
  dndObserver?: DndObserver<any> | null;
}

type MaybeSensor<S extends Sensor> = MaybeAccessor<S | null>;

export function useDraggable<S extends Sensor[] = Sensor[]>(
  sensors: MaybeSensor<S[number]>[],
  settingsInput?: MaybeAccessor<UseDraggableSettings<S> | undefined>,
): Accessor<Draggable<S> | null> {
  const resolvedSensors = createMemo(() => {
    return sensors.map((sensor) => resolveMaybeAccessor(sensor)).filter(Boolean) as S;
  });

  const resolvedSettings = createMemo(() => resolveMaybeAccessor(settingsInput));
  const idAccessor = createMemo(() => resolvedSettings()?.id);
  const overrideObserver = createMemo(() => resolvedSettings()?.dndObserver);
  const draggableOptions = createMemo(() => {
    const current = resolvedSettings();
    if (!current) return undefined;
    const { dndObserver: _ignoredObserver, id: _ignoredId, ...rest } = current;
    return rest as Partial<DraggableOptions<S>>;
  });
  const normalizedSettings = createMemo(() => draggableOptions() || {});

  const observerFromContext = useDndObserverContext<any>();
  const effectiveObserver = createMemo(() => {
    const override = overrideObserver();
    return override === undefined ? observerFromContext() : override;
  });

  const [draggable, setDraggable] = createSignal<Draggable<S> | null>(null);
  let draggableRef: Draggable<S> | null = null;
  let appliedId = idAccessor();
  let appliedSettings = normalizedSettings();
  let appliedObserver = effectiveObserver();

  const destroyDraggable = () => {
    if (!draggableRef) return;
    draggableRef.destroy();
    draggableRef = null;
    setDraggable(null);
  };

  const createDraggableInstance = () => {
    destroyDraggable();
    const sensorsList = resolvedSensors();
    if (!sensorsList.length) return;
    const options = normalizedSettings();
    const id = idAccessor();
    const instance = new Draggable<S>(sensorsList, {
      id,
      ...options,
    });
    const observer = effectiveObserver();
    observer?.addDraggables([instance]);
    draggableRef = instance;
    appliedId = id;
    appliedSettings = options;
    appliedObserver = observer;
    setDraggable(instance);
  };

  createEffect(() => {
    const sensorsList = resolvedSensors();
    if (!sensorsList.length) {
      destroyDraggable();
      return;
    }
    const current = draggableRef;
    if (!current) {
      createDraggableInstance();
      return;
    }
    const sensorsChanged =
      sensorsList.length !== current.sensors.length ||
      sensorsList.some((sensor) => !current.sensors.includes(sensor));
    if (sensorsChanged) {
      createDraggableInstance();
    }
  });

  createEffect(() => {
    const current = draggableRef;
    if (!current) return;
    const nextId = idAccessor();
    if (appliedId === nextId) return;
    createDraggableInstance();
  });

  createEffect(() => {
    const currentObserver = effectiveObserver();
    if (appliedObserver === currentObserver) return;
    const current = draggableRef;
    if (current) {
      appliedObserver?.removeDraggables([current]);
      currentObserver?.addDraggables([current]);
    }
    appliedObserver = currentObserver;
  });

  createEffect(() => {
    const current = draggableRef;
    if (!current) return;
    const nextSettings = normalizedSettings();
    if (areConfigsEqual(appliedSettings, nextSettings)) return;
    current.updateSettings(current['_parseSettings'](nextSettings));
    appliedSettings = nextSettings;
  });

  onCleanup(destroyDraggable);

  return draggable;
}
